mapper.select:
select

from t_biam_user_access_log ual


        AND ual.user_id IN

            #{item}



        AND ual.phone = #{inputDto.phone}


        AND LOWER(ual.real_name) LIKE LOWER(CONCAT('%', #{inputDto.realName}, '%'))


        AND ual.operate_source = #{inputDto.operateSource}


        AND ual.module = #{inputDto.module}


        AND ual.module_entity = #{inputDto.moduleEntity}


        AND ual.operate_type = #{inputDto.operateType}


        AND LOWER(ual.operate_name) LIKE LOWER(CONCAT('%', #{inputDto.operateName}, '%'))


        AND ual.action_status = #{inputDto.actionStatus}


        AND ual.http_status = #{inputDto.httpStatus}


        AND LOWER(ual.request_path) LIKE LOWER(CONCAT('%', #{inputDto.requestPath}, '%'))


        AND ual.client_ip = #{inputDto.clientIp}


        AND ual.trace_id = #{inputDto.traceId}


        AND ual.create_time >= #{inputDto.createStartTime}


        AND ual.create_time <= #{inputDto.createEndTime}


ORDER BY ual.create_time DESC
